<script setup lang="ts">
import InvestmentExperiments from './InvestmentExperiments.vue';
import {ref,computed,watch,onBeforeUnmount} from 'vue';import {apiError} from './apiError';
const props=defineProps<{projectId:string;section:string}>();
const emit=defineEmits<{context:[value:any]}>();
const experimentParameters=ref<any>(null);
const project=ref<any>(null),engineering=ref<any>(null),jobs=ref<any[]>([]),job=ref<any>(null),candidates=ref<any[]>([]);
const error=ref(''),busy=ref(false),name=ref('多阶段源储机会约束配置'),minutes=ref(60),steps=ref(24);
const probability=ref(.95),targetPolicy=ref('every_step'),riskScope=ref('per_period'),discount=ref(.06),salvage=ref('none'),budget=ref(''),wall=ref(600),gap=ref(.001);
const protectedClasses=ref(['基本保障','居民生活']);const selectedTrace=ref(0);
const stages=ref<any[]>([{name:'近期',year:2026,duration_years:1,budget_yuan:'',load_scale:1,annual_occurrences:1}]);
const scenarioText=ref(JSON.stringify([{id:'normal',name:'正常网供研究示例',weight:.8,grid_available_kw:[1000],provenance:'人工研究示例，需真实样本替换'},{id:'outage',name:'外部供电中断示例',weight:.2,grid_available_kw:[0],provenance:'人工研究示例，非地区校准概率'}],null,2));
const validationText=ref('[]'),advanced=ref(JSON.stringify({base:{time_limit_seconds:30},existing_retirement_year:{},existing_annual_maintenance_yuan:{},shortage_yuan_per_kwh:{},probability_provenance:'用户研究权重，非已校准地区概率'},null,2));
const jointText=ref(JSON.stringify({primary_candidates:[],switches:[],terminals:[],controllers:[],communication_links:[],budget_yuan:null,objective:'保供可靠性与投资综合',provenance:'待工程台账和课题3算法确认'},null,2));
const flexText=ref(JSON.stringify({zones:[],tie_lines:[],normally_open_switches:[],islanding_rules:[],source_priority:[],communication_dependencies:[],objective:'孤岛供电与恢复时间综合',provenance:'待拓扑、开关和控制策略确认'},null,2));
const terminal=new Set(['succeeded','incomplete','failed','cancelled','interrupted']);
const statusNames:Record<string,string>={queued:'排队',running:'计算中',cancel_requested:'等待取消',succeeded:'模型计算结束',incomplete:'结果未完整',failed:'失败',cancelled:'已取消',interrupted:'中断',passed:'通过',not_checked:'未校核'};
let generation=0,selection=0,timer:ReturnType<typeof setTimeout>|undefined;
const result=computed(()=>job.value?.result),activeJob=computed(()=>job.value&&!terminal.has(job.value.status));
watch(()=>[engineering.value,job.value],()=>emit('context',{engineering:engineering.value,job:job.value}),{immediate:true});
const trace=computed(()=>result.value?.scenario_results?.[selectedTrace.value]);
const fmt=(n:any,d=3)=>typeof n==='number'?n.toFixed(d):'—';
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function refresh(){const g=++generation;++selection;clearTimeout(timer);job.value=null;jobs.value=[];project.value=null;engineering.value=null;candidates.value=[];experimentParameters.value=null;error.value='';busy.value=false;if(!props.projectId)return;try{const[p,e,h]=await Promise.all([api('/api/projects/'+props.projectId),api('/api/engineering/projects/'+props.projectId),api('/api/study-jobs?project_id='+props.projectId)]);if(g!==generation)return;project.value=p;engineering.value=e;discount.value=e.inventory.economics.discount_rate;budget.value=e.inventory.economics.investment_limit_yuan==null?'':String(e.inventory.economics.investment_limit_yuan);candidates.value=[...e.inventory.sources,...e.inventory.storage].filter((a:any)=>!a.existing).map((a:any)=>({asset_id:a.id,name:a.name,node:a.node,power_kw:a.rated_kw??a.power_kw,energy_kwh:a.energy_kwh,enabled:false,sizing_mode:'block',fuel_budget_mode:'fixed_stock',minimum_power_fraction:.05,maximum_power_fraction:1,minimum_energy_fraction:.05,maximum_energy_fraction:1,power_capex_yuan:'',energy_capex_yuan:'',power_maintenance_yuan:0,energy_maintenance_yuan:0,fixed_capex_yuan:0,fixed_annual_maintenance_yuan:0,minimum_duration_hours:.25,maximum_duration_hours:'',capex_yuan:'',annual_maintenance_yuan:0,lifetime_years:e.inventory.economics.lifetime_years,earliest_year:'',latest_year:'',provenance:'用户研究成本，需工程确认'}));jobs.value=h.filter((j:any)=>j.module==='investment');if(jobs.value.length)await inspect(jobs.value[0].id)}catch(e){if(g===generation)error.value=String(e)}}
async function inspect(id:string){clearTimeout(timer);const g=generation,s=++selection;try{const d=await api('/api/study-jobs/'+id+'?include_input=true&include_result=true');if(g!==generation||s!==selection||d.project_id!==props.projectId)return;job.value=d;selectedTrace.value=0;if(!terminal.has(d.status))timer=setTimeout(()=>poll(id,g),400)}catch(e){if(g===generation&&s===selection)error.value=String(e)}}
async function poll(id:string,g:number){if(g!==generation||job.value?.id!==id)return;try{const d=await api('/api/study-jobs/'+id);if(g!==generation||job.value?.id!==id)return;if(terminal.has(d.status)){const full=await api('/api/study-jobs/'+id+'?include_input=true&include_result=true');if(g!==generation||job.value?.id!==id)return;job.value=full;selectedTrace.value=0;const h=await api('/api/study-jobs?project_id='+props.projectId);if(g===generation)jobs.value=h.filter((j:any)=>j.module==='investment')}else{job.value=d;timer=setTimeout(()=>poll(id,g),1200)}}catch(e){if(g===generation&&job.value?.id===id){error.value=String(e);timer=setTimeout(()=>poll(id,g),3000)}}}
function addStage(){const last=stages.value[stages.value.length-1];stages.value.push({name:'阶段'+(stages.value.length+1),year:last?last.year+last.duration_years:2026,duration_years:1,budget_yuan:'',load_scale:1,annual_occurrences:1})}
function optional(v:any){return v===''||v==null?null:Number(v)}
function candidatePayload(c:any){
 const continuous=c.sizing_mode==='continuous',battery=continuous&&c.energy_kwh!=null;
 const amounts=battery?[c.power_capex_yuan,c.energy_capex_yuan]:[c.capex_yuan];
 if(amounts.some(v=>v===''||v==null||!Number.isFinite(Number(v))))throw Error('请明确填写所选候选的投资成本，连续储能须分别填写功率/能量成本，0元也需显式录入');
 const data:any={asset_id:c.asset_id,sizing_mode:c.sizing_mode,fuel_budget_mode:c.fuel_budget_mode,capex_yuan:battery?Number(c.power_capex_yuan)+Number(c.energy_capex_yuan):Number(c.capex_yuan),annual_maintenance_yuan:battery?Number(c.power_maintenance_yuan)+Number(c.energy_maintenance_yuan):c.annual_maintenance_yuan,lifetime_years:c.lifetime_years,earliest_year:optional(c.earliest_year),latest_year:optional(c.latest_year),provenance:c.provenance,fixed_capex_yuan:c.fixed_capex_yuan,fixed_annual_maintenance_yuan:c.fixed_annual_maintenance_yuan};
 if(continuous)Object.assign(data,{minimum_power_fraction:c.minimum_power_fraction,maximum_power_fraction:c.maximum_power_fraction});
 if(battery)Object.assign(data,{minimum_energy_fraction:c.minimum_energy_fraction,maximum_energy_fraction:c.maximum_energy_fraction,power_capex_yuan:Number(c.power_capex_yuan),energy_capex_yuan:Number(c.energy_capex_yuan),power_maintenance_yuan:c.power_maintenance_yuan,energy_maintenance_yuan:c.energy_maintenance_yuan,minimum_duration_hours:c.minimum_duration_hours,maximum_duration_hours:optional(c.maximum_duration_hours)});
 return data
}
function planningParameters(){if(!project.value||!engineering.value?.revision)throw Error('请先保存工程和设备台账');const selected=candidates.value.filter(c=>c.enabled);if(!selected.length)throw Error('请在候选资源中勾选至少一个未建设源储设备');
 const extra=JSON.parse(advanced.value);if(!extra||Array.isArray(extra)||typeof extra!=='object')throw Error('高级参数须为JSON对象');const{base:baseExtra={},...settings}=extra;
 const base={...baseExtra,project_id:props.projectId,project_revision:project.value.revision,engineering_revision:engineering.value.revision,steps:steps.value,step_hours:minutes.value/60};
 const investment=selected.map(candidatePayload);
 const periods=stages.value.map(p=>({...p,budget_yuan:optional(p.budget_yuan)}));
 const parameters={...settings,base,name:name.value,candidates:investment,stages:periods,scenarios:JSON.parse(scenarioText.value),validation_scenarios:JSON.parse(validationText.value),required_probability:probability.value,risk_scope:riskScope.value,target_policy:targetPolicy.value,protected_classes:protectedClasses.value,discount_rate:discount.value,salvage_policy:salvage.value,total_investment_budget_yuan:optional(budget.value),wall_time_seconds:wall.value,relative_gap:gap.value};
 return parameters
}
async function readJointDraft(){try{const d=await api('/api/drafts/一二次协同规划?project_id='+encodeURIComponent(props.projectId));if(d.values)jointText.value=JSON.stringify(d.values,null,2)}catch(e){error.value=String(e)}}
async function readFlexDraft(){try{const d=await api('/api/drafts/灵活组网?project_id='+encodeURIComponent(props.projectId));if(d.values)flexText.value=JSON.stringify(d.values,null,2)}catch(e){error.value=String(e)}}
async function saveJointDraft(){try{const value=JSON.parse(jointText.value);if(!value||Array.isArray(value)||typeof value!=='object')throw Error('一二次协同参数必须是JSON对象');const r=await api('/api/drafts/一二次协同规划?project_id='+encodeURIComponent(props.projectId),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:value})});error.value='已保存一二次协同规划草稿 · '+r.updated}catch(e){error.value=String(e)}}
async function saveFlexDraft(){try{const value=JSON.parse(flexText.value);if(!value||Array.isArray(value)||typeof value!=='object')throw Error('灵活组网参数必须是JSON对象');const r=await api('/api/drafts/灵活组网?project_id='+encodeURIComponent(props.projectId),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:value})});error.value='已保存灵活组网草稿 · '+r.updated}catch(e){error.value=String(e)}}
function exportDraft(name:string,text:string){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name+'-'+props.projectId.slice(0,8)+'.json';a.click()}
function loadExperimentBaseline(){try{experimentParameters.value=planningParameters();error.value=''}catch(e){error.value=String(e)}}
async function submit(){const g=generation,s=++selection;clearTimeout(timer);busy.value=true;error.value='';try{const parameters=planningParameters();
 const d=await api('/api/study-jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'investment',parameters})});if(g!==generation||s!==selection)return;job.value=d;jobs.value=[d,...jobs.value];timer=setTimeout(()=>poll(d.id,g),200)}catch(e){if(g===generation&&s===selection)error.value=String(e)}finally{if(g===generation)busy.value=false}}
async function action(type:string){const id=job.value?.id,g=generation,s=++selection;if(!id)return;try{const d=await api('/api/study-jobs/'+id+'/'+type,{method:'POST'});if(g===generation&&s===selection){job.value=d;clearTimeout(timer);timer=setTimeout(()=>poll(d.id,g),200)}}catch(e){if(g===generation&&s===selection)error.value=String(e)}}
watch(()=>props.projectId,refresh,{immediate:true});watch(()=>[props.projectId,props.section],()=>{if(props.projectId&&props.section==='一二次协同规划')readJointDraft();if(props.projectId&&props.section==='灵活组网')readFlexDraft()},{immediate:true});onBeforeUnmount(()=>{++generation;++selection;clearTimeout(timer)});
</script>
<template>
<article><h3>源储协同配置 · {{section}}</h3><p>联合优化候选源储的接入位置、建设年份和场景运行，使用带权联合机会约束与折现成本。支持固定设备块与连续定容混合配置，连续储能独立优化功率和能量。每个ID最多投运一次，追加/替换单元分别建ID；未建设设备不贡献出力、储能初始电量、无功或构网能力。</p><p v-if="error" class="error">{{error}}</p><div class="actions"><button @click="refresh" :disabled="busy">重新读取台账与任务</button><span>工程版本 {{project?.revision||'—'}} / 台账版本 {{engineering?.revision||0}}</span></div>
<template v-if="section==='候选资源'"><p>从“数据管理”的电源/储能台账读取“未建设”设备。投资与维护费均为元，默认不假定免费设备；源曲线、燃料和储能参数仍须在台账核实。</p><p v-if="!candidates.length" class="notice">尚无未建设源储，请先在台账中新增候选设备。</p><div class="scroll"><table><tr><th>参与</th><th>设备/节点</th><th>容量方式</th><th>参考上限</th><th>满额参考投资 元</th><th>满额参考年维护 元</th><th>寿命 年</th><th>最早/最晚投运年</th><th>来源</th></tr><tr v-for="c in candidates" :key="c.asset_id"><td><label><input type="checkbox" v-model="c.enabled">选择 {{c.asset_id}}</label></td><td>{{c.asset_id}} · {{c.name}} / {{c.node}}</td><td><select :aria-label="c.asset_id+' 容量方式'" v-model="c.sizing_mode"><option value="block">固定设备块</option><option value="continuous">连续定容</option></select></td><td>{{c.power_kw}} kW<span v-if="c.energy_kwh!=null"> / {{c.energy_kwh}} kWh</span></td><td><span v-if="c.sizing_mode==='continuous'&&c.energy_kwh!=null">功率/能量分项见下方</span><input v-else :aria-label="c.asset_id+' 投资成本 元'" type="number" v-model="c.capex_yuan" min="0" placeholder="必填"></td><td><span v-if="c.sizing_mode==='continuous'&&c.energy_kwh!=null">分项见下方</span><input v-else type="number" v-model.number="c.annual_maintenance_yuan" min="0"></td><td><input :aria-label="c.asset_id+' 寿命 年'" type="number" v-model.number="c.lifetime_years" min="1" max="100"></td><td><input type="number" v-model="c.earliest_year" placeholder="不限"><input type="number" v-model="c.latest_year" placeholder="不限"></td><td><input v-model="c.provenance"></td></tr></table></div>
<p>连续定容以台账功率/能量作为可建参考上限，比例0—1，正的最小比例至少0.0001。电源曲线、爬坡与无功能力按功率比缩放；可运行时长不缩放。燃料默认使用安装后的台账固定库存，也可选择按功率比缩放。储能效率及技术类型保持不变。这些线性设计假设和参考成本需工程确认。</p>
<details v-for="c in candidates.filter(c=>c.enabled)" :key="c.asset_id" :open="c.sizing_mode==='continuous'" class="design"><summary>{{c.asset_id}} · 定容范围与固定费用</summary><div class="fields">
<label>固定建设费 元<input :aria-label="c.asset_id+' 固定建设费 元'" type="number" min="0" v-model.number="c.fixed_capex_yuan"></label><label>固定年维护 元<input type="number" min="0" v-model.number="c.fixed_annual_maintenance_yuan"></label>
<template v-if="c.sizing_mode==='continuous'"><label>最小功率比例<input :aria-label="c.asset_id+' 最小功率比例'" type="number" min=".0001" max="1" step=".01" v-model.number="c.minimum_power_fraction"></label><label>最大功率比例<input type="number" min=".0001" max="1" step=".01" v-model.number="c.maximum_power_fraction"></label>
<label v-if="c.energy_kwh==null">燃料预算方式<select :aria-label="c.asset_id+' 燃料预算方式'" v-model="c.fuel_budget_mode"><option value="fixed_stock">安装后台账固定库存</option><option value="proportional">按参考功率比例缩放</option></select></label><template v-if="c.energy_kwh!=null"><label>最小能量比例<input type="number" min=".0001" max="1" step=".01" v-model.number="c.minimum_energy_fraction"></label><label>最大能量比例<input type="number" min=".0001" max="1" step=".01" v-model.number="c.maximum_energy_fraction"></label>
<label>满额参考功率投资 元<input :aria-label="c.asset_id+' 功率投资 元'" type="number" min="0" v-model="c.power_capex_yuan" placeholder="必填"></label><label>满额参考能量投资 元<input :aria-label="c.asset_id+' 能量投资 元'" type="number" min="0" v-model="c.energy_capex_yuan" placeholder="必填"></label>
<label>满额功率年维护 元<input type="number" min="0" v-model.number="c.power_maintenance_yuan"></label><label>满额能量年维护 元<input type="number" min="0" v-model.number="c.energy_maintenance_yuan"></label>
<label>最小额定储能时长 h<input :aria-label="c.asset_id+' 最小储能时长 h'" type="number" min="0" step=".25" v-model.number="c.minimum_duration_hours"></label><label>最大额定储能时长 h<input type="number" min=".001" step=".25" v-model="c.maximum_duration_hours" placeholder="不限"></label>
</template></template></div><p>固定费用按是否安装计收。满额分项成本×选定比例得到容量费用；储能时长=额定能量÷额定功率，为研究设计约束，需按厂家范围修改。</p></details></template>
<template v-if="section==='目标与约束'"><div class="fields"><label>任务名称<input v-model="name"></label><label>目标达标概率<input type="number" v-model.number="probability" min=".001" max="1" step=".01"></label><label>保供目标判据<select v-model="targetPolicy"><option value="every_step">目标窗口内每步达标</option><option value="interruption_budget">按台账最大连续中断预算</option></select></label><label>联合范围<select v-model="riskScope"><option value="per_period">每个时期内负荷与时段联合</option><option value="all_periods">全部时期与负荷时段联合</option></select></label><label>折现率<input type="number" v-model.number="discount" min="0" max="1" step=".01"></label><label>总投资预算 元<input type="number" v-model="budget" min="0" placeholder="留空使用台账预算或不限"></label><label>期末残值<select v-model="salvage"><option value="none">不计残值</option><option value="linear_remaining_life">按剩余寿命线性计残值</option></select></label><label>时间步 min<select v-model.number="minutes"><option v-for="m in [1,5,15,30,60]" :value="m">{{m}}</option></select></label><label>事件计算步数<input type="number" v-model.number="steps" min="1" max="672"></label><label>总时限 s<input type="number" v-model.number="wall" min="1" max="3600"></label><label>允许相对gap<input type="number" v-model.number="gap" min="0" max=".2" step=".001"></label></div>
<div class="checks"><label v-for="c in ['基本保障','居民生活','一般负荷']"><input type="checkbox" :value="c" v-model="protectedClasses">保护 {{c}}</label></div><p>可选择目标窗口内每步达标，或按台账是否允许中断及最大连续中断时长达标；两者都需覆盖完整目标窗口。预算模式不是累计中断限额，主动削减低于最低供电比例仍计中断，0需求会结束中断段。其他负荷仍参与电量平衡与缺供成本。样本权重须归一、训练/验证输入须分开。</p>
<h4>训练场景 JSON</h4><p>下方初始值为人工示例。场景未填网供时按0处理；grid_available_kw、设备可用率、线路状态与源荷曲线可逐步指定。storage_temperature_factor按储能ID同时降额功率和能量；stage_overrides按建设年份覆盖运行剖面，表示同一条未来轨迹。投资跨所有场景共享，不按已知故障单独建设。</p><textarea aria-label="训练场景 JSON" v-model="scenarioText" rows="15" spellcheck="false"></textarea>
<h4>独立样本外验证 JSON</h4><p>留空数组表示未提供验证集，不会显示已通过样本外验证。未知样本保留在概率上下界，不将加权验证比例冒充真实地区风险保证。</p><textarea aria-label="独立样本外验证 JSON" v-model="validationText" rows="7" spellcheck="false"></textarea>
<details><summary>已有退役年、分类缺供成本、来源及调度高级参数</summary><textarea aria-label="规划高级参数 JSON" v-model="advanced" rows="10" spellcheck="false"></textarea></details></template>
<template v-if="section==='一二次协同规划'"><h4>一次网架与二次控制联合布局草稿</h4><p>明确一次线路/开关与二次终端、控制器、通信链路的候选对象及成本约束。保存内容供模块交接接口读取；当前不生成联合规划结论，也不替代课题3真实算法。</p><textarea aria-label="一二次协同规划参数 JSON" v-model="jointText" rows="18" spellcheck="false"></textarea><div class="actions"><button @click="saveJointDraft">保存协同规划草稿</button><button @click="exportDraft('一二次协同规划',jointText)">导出 JSON</button><button @click="jointText=JSON.stringify({primary_candidates:[],switches:[],terminals:[],controllers:[],communication_links:[],budget_yuan:null,objective:'保供可靠性与投资综合',provenance:'待工程台账和课题3算法确认'},null,2)">恢复模板</button></div><p>字段：primary_candidates、switches、terminals、controllers、communication_links、budget_yuan、objective、provenance。</p></template><template v-if="section==='灵活组网'"><h4>灵活组网与分区自治草稿</h4><p>描述分区、联络线、常开开关、孤岛规则、源储优先级和通信依赖，供后续一次二次联合规划与黑启动恢复使用。当前仅保存配置，不生成自动重构或稳定性结论。</p><textarea aria-label="灵活组网参数 JSON" v-model="flexText" rows="18" spellcheck="false"></textarea><div class="actions"><button @click="saveFlexDraft">保存灵活组网草稿</button><button @click="exportDraft('灵活组网',flexText)">导出 JSON</button><button @click="flexText=JSON.stringify({zones:[],tie_lines:[],normally_open_switches:[],islanding_rules:[],source_priority:[],communication_dependencies:[],objective:'孤岛供电与恢复时间综合',provenance:'待拓扑、开关和控制策略确认'},null,2)">恢复模板</button></div><p>字段：zones、tie_lines、normally_open_switches、islanding_rules、source_priority、communication_dependencies、objective、provenance。</p></template><template v-if="section==='规划阶段'"><p>阶段须年份连续。投资期初支付、运营维护期末支付；系统按所有可能退役年拆分运营期，不允许过期资产继续供电。事件频次×事件时长不得超过标准年的8760小时。缺正常运行样本时，成本只覆盖给定事件。</p><div class="scroll"><table><tr><th>阶段名称</th><th>开始年份</th><th>覆盖年数</th><th>新增投资预算 元</th><th>相对基准负荷系数</th><th>代表事件次数/年</th><th></th></tr><tr v-for="(p,i) in stages" :key="i"><td><input v-model="p.name"></td><td><input type="number" v-model.number="p.year"></td><td><input type="number" v-model.number="p.duration_years" min="1" max="50"></td><td><input type="number" v-model="p.budget_yuan" min="0" placeholder="不限"></td><td><input type="number" v-model.number="p.load_scale" min=".01" step=".1"></td><td><input type="number" v-model.number="p.annual_occurrences" min="0" step=".1"></td><td><button @click="stages.splice(i,1)" :disabled="stages.length===1">移除</button></td></tr></table></div><button @click="addStage" :disabled="stages.length>=8">增加建设阶段</button></template>
<button v-if="['候选资源','目标与约束','规划阶段'].includes(section)" class="primary" @click="submit" :disabled="busy||!engineering?.revision">{{busy?'正在冻结输入…':'提交多阶段机会约束配置'}}</button>
</article>
<article v-if="job"><h3>配置任务 · {{statusNames[job.status]||job.status}}</h3><p>{{job.name}} · {{job.id}} · 输入摘要 {{job.input_sha256}}</p><p v-if="job.input">冻结判据：{{job.input.parameters.risk_scope==='all_periods'?'跨全部时期联合':'各时期内联合'}}，概率≥{{job.input.parameters.required_probability}}，保护{{job.input.parameters.protected_classes.join(' / ')}}。数值为冻结输入对应结果。</p><p v-if="activeJob">原生联合求解在本任务独占子进程运行；取消只停止该求解子进程，模型构建与输出在检查点停止。异常退出保留数值模型及日志，不提交成功结果。</p><progress :value="job.progress?.fraction||0" max="1"></progress><p>{{job.progress?.phase}} · 变量{{job.progress?.variables||'—'}} / 模型{{job.progress?.models||'—'}}</p><p v-if="job.error" class="error">{{job.error}}</p><div class="actions"><button v-if="activeJob" @click="action('cancel')" :disabled="job.status==='cancel_requested'">请求取消</button><button v-else @click="action('retry')">冻结输入新建重试</button><a :href="'/api/study-jobs/'+job.id+'/download'">完整输入与结果 JSON</a><a v-if="result" :href="'/api/study-jobs/'+job.id+'/csv'">选址投运方案 CSV</a><a :href="'/api/study-jobs/'+job.id+'/log'" target="_blank">工作日志</a></div>
<template v-if="result"><p>本次配置目标判据：{{result.target_policy==='interruption_budget'?'台账最大连续中断预算':'目标窗口内每步达标'}}。</p><p v-if="result.status==='infeasible'" class="error">给定候选、预算、样本与静态约束不可行，未生成投资可行方案。</p><p v-else-if="result.status!=='complete'" class="notice">求解界限或验证尚未满足要求，结果未完整；已有可行解与求解界限见下方，不宣称已得最优方案。</p><p v-if="result.recommendation_status==='not_recommended_validation_failed'" class="error">样本外验证未达到目标，本方案不能作为已验证可靠方案。需保留独立验证数据并修订规划，不能用训练达标代替验证。</p>
<div class="metrics"><div>折现目标成本 元<strong>{{fmt(result.objective_yuan)}}</strong></div><div>求解下界 元<strong>{{fmt(result.solver.dual_bound_yuan)}}</strong></div><div>已校核相对gap<strong>{{fmt(result.solver.verified_relative_gap,6)}}</strong></div><div>变量 / 约束<strong>{{result.solver.variables}} / {{result.solver.constraints}}</strong></div></div><p>{{result.solver.message}}</p>
<h4>选址、容量与投运年份</h4><p v-if="result.objective_yuan!=null&&!result.selected_assets.length">当前目标下无需新增候选设备；已有设备与外部供电仍参与计算。</p><div class="scroll"><table><tr><th>设备/节点</th><th>方式 / 功率与能量比例</th><th>功率 kW</th><th>储能 kWh</th><th>投运年</th><th>退役年</th><th>投资 元</th></tr><tr v-for="a in result.selected_assets"><td>{{a.asset_id}} / {{a.node}}</td><td>{{a.sizing_mode==='continuous'?'连续':'设备块'}} / {{fmt(a.power_fraction??1,4)}} · {{a.energy_kwh==null?'—':fmt(a.energy_fraction??1,4)}}</td><td>{{fmt(a.power_kw)}}</td><td>{{fmt(a.energy_kwh)}}</td><td>{{a.commission_year}}</td><td>{{a.retirement_year}}</td><td>{{fmt(a.capex_yuan)}}</td></tr></table></div>
<template v-if="result.compliance"><h4>各运营期机会约束实际复核</h4><div class="scroll"><table><tr><th>时期</th><th>运营年份</th><th>模型承诺概率</th><th>实际达标概率</th><th>要求</th><th>有效源储</th></tr><tr v-for="p in result.compliance"><td>{{p.stage_name}}</td><td>{{p.year}}—{{p.end_year-1}}</td><td>{{fmt(p.assigned_probability,6)}}</td><td>{{fmt(p.actual_probability,6)}}</td><td>{{fmt(p.required_probability,6)}}</td><td>{{p.active_assets.join(', ')}}</td></tr></table></div><p>跨全部时期实际达标概率：{{fmt(result.all_periods_actual_probability,6)}}。各期边际达标不等于跨期联合达标。</p></template>
<div class="actions"><a :href="'/api/study-jobs/'+job.id+'/report'">配置研究报告 HTML</a><a v-if="result.objective_yuan!=null" :href="'/api/study-jobs/'+job.id+'/csv?dataset=cashflows'">逐年现金流 CSV</a><a v-if="result.compliance" :href="'/api/study-jobs/'+job.id+'/csv?dataset=compliance'">机会约束复核 CSV</a></div><h4>逐年现金流</h4><div class="scroll"><table><tr><th>年份</th><th>投资 元</th><th>维护 元</th><th>期望运营 元</th><th>期末残值 元</th><th>折现净成本 元</th></tr><tr v-for="r in result.cashflows"><td>{{r.year}}</td><td>{{fmt(r.capex_yuan)}}</td><td>{{fmt(r.annual_maintenance_yuan)}}</td><td>{{fmt(r.expected_operating_yuan)}}</td><td>{{fmt(r.terminal_salvage_yuan)}}</td><td>{{fmt(r.discounted_total_yuan)}}</td></tr></table></div>
<h4>样本外验证</h4><p v-if="!result.validation.length">未提供或尚未执行样本外验证。</p><div v-else class="scroll"><table><tr><th>运营年份</th><th>成功概率下界</th><th>成功概率上界</th><th>未知权重</th></tr><tr v-for="v in result.validation"><td>{{v.year}}—{{v.end_year-1}}</td><td>{{fmt(v.success_probability_lower,6)}}</td><td>{{fmt(v.success_probability_upper,6)}}</td><td>{{fmt(v.unknown_probability,6)}}</td></tr></table></div><p v-if="result.validation_all_periods">样本外跨期联合范围：{{fmt(result.validation_all_periods.success_probability_lower,6)}}—{{fmt(result.validation_all_periods.success_probability_upper,6)}}。</p>
<h4>校核与未完成项</h4><div class="scroll"><table><tr><th>校核项</th><th>状态</th></tr><tr v-for="c in result.checks"><td>{{c.name}}</td><td>{{statusNames[c.status]||c.status}}</td></tr></table></div>
<template v-if="result.scenario_results?.length"><h4>场景逐设备运行结果</h4><label>查看场景<select v-model.number="selectedTrace"><option v-for="(t,i) in result.scenario_results" :value="i">时期{{t.period+1}} · {{t.scenario_id}}</option></select></label><p>此处为联合经济规划的后验运行，不是旧分层缺供最小化策略。</p><div class="scroll" v-if="trace"><table><tr><th>时间</th><th>负荷 kW</th><th>供电 kW</th><th>未供 kW</th><th>网供 kW</th></tr><tr v-for="r in trace.result.rows"><td>{{r.timestamp}}</td><td>{{fmt(r.load_kw)}}</td><td>{{fmt(r.served_kw)}}</td><td>{{fmt(r.total_unsupplied_kw)}}</td><td>{{fmt(r.grid_kw)}}</td></tr></table></div><template v-if="trace"><h4>台账中断指标（配置达标以所选判据为准）</h4><div class="scroll"><table><tr><th>负荷</th><th>最大连续中断 h</th><th>累计中断 h</th><th>允许连续中断 h</th><th>台账目标判定</th></tr><tr v-for="l in trace.result.load_metrics"><td>{{l.id}}</td><td>{{fmt(l.maximum_target_interruption_hours)}}</td><td>{{fmt(l.total_target_interruption_hours)}}</td><td>{{fmt(l.allowed_consecutive_interruption_hours)}}</td><td>{{statusNames[l.target_status]||l.target_status}}</td></tr></table></div></template></template>
<details><summary>模型范围与证据</summary><p v-for="s in result.scope">{{s}}</p><pre>{{JSON.stringify(result.certificate||result.solver,null,2)}}</pre></details>
</template></article>
<article><h3>本工程多阶段配置档案</h3><p v-if="!jobs.length">尚无联合配置任务。旧枚举试算档案仍可在“方案与报告 → 配置方案”查阅。</p><button class="record" v-for="j in jobs" :key="j.id" @click="inspect(j.id)">{{j.name}} · {{statusNames[j.status]||j.status}} · {{new Date(j.created*1000).toLocaleString()}}</button></article>
<InvestmentExperiments v-show="section==='目标与约束'||section==='配置结果'" :project-id="projectId" :parameters="experimentParameters" @load-baseline="loadExperimentBaseline"/>
</template>
<style scoped>.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:20px 0}.fields label{display:flex;justify-content:space-between;align-items:center;gap:12px}.fields input,.fields select{width:210px}input,select{padding:7px;border:1px solid #c8dcdf;max-width:100%}td input{width:120px}input[type=checkbox]{width:auto}.checks{display:flex;flex-wrap:wrap;gap:20px;margin:18px 0}.checks label{display:flex;align-items:center;gap:8px}.scroll{overflow:auto;max-height:430px;margin:18px 0}td,th{white-space:nowrap}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:16px;margin:18px 0}textarea{width:100%;box-sizing:border-box;font-family:monospace}.primary{margin:24px 0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0}.metrics strong{display:block;margin-top:10px}progress{width:100%;height:18px}.record{display:block;margin:12px 0}pre{max-height:320px;overflow:auto}details{margin:20px 0}@media(max-width:1050px){.fields{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}}</style>



